create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table public.anime (anilist_id bigint primary key,mal_id bigint,title text not null,title_romaji text,title_english text,title_native text,description text,cover_url text,banner_url text,format text,status text,season text,season_year int,total_episodes int,duration int,genres text[] not null default '{}',score int,is_adult boolean not null default false,mappings jsonb,has_streams boolean not null default false,not_found_on_anivexa boolean not null default false,episodes_synced_at timestamptz,last_checked_at timestamptz,last_resynced_at timestamptz,franchise_checked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.episodes (play_id text primary key,anilist_id bigint not null references public.anime(anilist_id) on delete cascade,episode_number int not null,title text,title_japanese text,title_romaji text,description text,image_url text,air_date date,duration int,filler boolean not null default false,recap boolean not null default false,sub_providers jsonb not null default '[]',dub_providers jsonb not null default '[]',resolved_provider text,resolved_audio text,resolved_at timestamptz,needs_resync boolean not null default false,resync_requested_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(anilist_id,episode_number));
create table public.anime_import_queue (anilist_id bigint primary key,reason text not null default 'seen',priority int not null default 0,status text not null default 'pending' check(status in('pending','processing','done','error','not_found')),attempts int not null default 0,last_error text,snapshot jsonb,next_attempt_at timestamptz not null default now(),queued_at timestamptz not null default now(),processed_at timestamptz);
create table public.pending_sync (id bigserial primary key,anilist_id bigint not null,episode_number int not null,status text not null default 'pending' check(status in('pending','processing','done','error')),attempts int not null default 0,last_error text,next_attempt_at timestamptz not null default now(),created_at timestamptz not null default now(),processed_at timestamptz,unique(anilist_id,episode_number));
create table public.episode_check_state (anilist_id bigint primary key references public.anime(anilist_id) on delete cascade,last_checked_at timestamptz not null default now(),last_missing int not null default 0,last_error text);
create table public.cron_runs (id bigserial primary key,job text not null,started_at timestamptz not null default now(),finished_at timestamptz,ok boolean,stats jsonb,error text);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,username text unique,display_name text,avatar_url text,title_language text not null default 'english' check(title_language in('english','romaji','native')),show_adult boolean not null default false,subtitle_language text not null default 'English',preferred_audio text not null default 'sub' check(preferred_audio in('sub','dub')),auto_next boolean not null default true,auto_skip boolean not null default false,video_quality text not null default 'auto',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.favourites(user_id uuid not null references auth.users(id) on delete cascade,anilist_id bigint not null,snapshot jsonb,created_at timestamptz not null default now(),primary key(user_id,anilist_id));
create table public.watchlist(user_id uuid not null references auth.users(id) on delete cascade,anilist_id bigint not null,status text not null check(status in('watching','planning','completed','dropped','paused','repeating')),progress int not null default 0,snapshot jsonb,updated_at timestamptz not null default now(),primary key(user_id,anilist_id));
create table public.watch_progress(user_id uuid not null references auth.users(id) on delete cascade,anilist_id bigint not null,episode_number int not null,position_seconds int not null default 0,duration_seconds int,audio text not null default 'sub' check(audio in('sub','dub')),completed boolean not null default false,updated_at timestamptz not null default now(),primary key(user_id,anilist_id,episode_number));
create table public.comments(id uuid primary key default gen_random_uuid(),anilist_id bigint not null,episode_number int,user_id uuid not null references auth.users(id) on delete cascade,parent_id uuid references public.comments(id) on delete cascade,body text not null check(char_length(body) between 1 and 2000),is_spoiler boolean not null default false,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comment_reactions(comment_id uuid not null references public.comments(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,value smallint not null check(value in(1,-1)),created_at timestamptz not null default now(),primary key(comment_id,user_id));
create view public.public_profiles as select id,username,display_name,avatar_url from public.profiles; grant select on public.public_profiles to anon,authenticated;
create index anime_status_idx on public.anime(status); create index anime_season_year_idx on public.anime(season_year); create index episodes_anilist_idx on public.episodes(anilist_id,episode_number); create index watchlist_user_status_idx on public.watchlist(user_id,status,updated_at desc);
